public.hxos_claim_universal_v1_work_order_compensation_v2(integer,integer)|CREATE OR REPLACE FUNCTION public.hxos_claim_universal_v1_work_order_compensation_v2(requested_limit integer, minimum_age_seconds integer)
 RETURNS SETOF public.universal_v1_work_order_compensation_commands
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  request_authority RECORD;
  candidate public.universal_v1_work_order_compensation_commands%ROWTYPE;
  claimed_count INTEGER := 0;
BEGIN
  PERFORM hx_authority.assert_universal_v1_work_order_bootstrap_seal_v1();
  IF requested_limit IS NULL OR requested_limit < 1 OR requested_limit > 100
     OR minimum_age_seconds IS NULL
     OR minimum_age_seconds < 5 OR minimum_age_seconds > 3600 THEN
    RAISE EXCEPTION 'HXUV1-WOCMD-60: compensation claim bounds are invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO STRICT request_authority
    FROM hx_authority.build_universal_v1_work_order_command_request_v1(
      'CLAIM_WORK_ORDER_COMPENSATION',
      pg_catalog.jsonb_build_object(
        'limit', requested_limit,
        'minimum_age_seconds', minimum_age_seconds
      )
    );

  FOR candidate IN
    SELECT *
      FROM public.claim_universal_v1_work_order_compensations(
        requested_limit,
        minimum_age_seconds
      )
  LOOP
    claimed_count := claimed_count + 1;
    PERFORM hx_authority.record_universal_v1_work_order_command_execution_v1(
      request_authority.target_authority_id,
      NULL,
      'CLAIM_WORK_ORDER_COMPENSATION',
      request_authority.canonical_request_sha256,
      NULL,
      'hustlexp.work-order-compensation-worker.v1',
      NULL,
      candidate.compensation_command_id,
      NULL,
      'WORKER_CLAIMED',
      pg_catalog.jsonb_build_object(
        'compensation_command_id', candidate.compensation_command_id,
        'work_order_idempotency_key', candidate.work_order_idempotency_key
      )
    );
    RETURN NEXT candidate;
  END LOOP;
  IF claimed_count = 0 THEN
    PERFORM hx_authority.record_universal_v1_work_order_command_execution_v1(
      request_authority.target_authority_id,
      NULL,
      'CLAIM_WORK_ORDER_COMPENSATION',
      request_authority.canonical_request_sha256,
      NULL,
      'hustlexp.work-order-compensation-worker.v1',
      NULL,
      NULL,
      NULL,
      'WORKER_CLAIMED',
      pg_catalog.jsonb_build_object('claimed_count', 0)
    );
  END IF;
  RETURN;
END;
$function$

public.hxos_decide_authenticated_change_order_v13(text,jsonb)|CREATE OR REPLACE FUNCTION public.hxos_decide_authenticated_change_order_v13(actor_assertion_token text, command_payload jsonb)
 RETURNS TABLE(result jsonb, actor_user_id uuid, actor_assertion_id uuid, actor_request_sha256 text, target_authority_id uuid, command_release_sha256 text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  request RECORD; actor RECORD; context JSONB; proposal public.task_scope_change_proposals%ROWTYPE;
  approval RECORD; key_value TEXT; party_value TEXT; decision_value TEXT; request_sha CHAR(64);
  replay BOOLEAN:=FALSE; changed_count BIGINT;
