    END IF;
  END IF;
  IF pg_catalog.abs(EXTRACT(EPOCH FROM pg_catalog.clock_timestamp())*1000-
      (command_payload->>'client_timestamp_epoch_ms')::NUMERIC)>300000 THEN
    RAISE EXCEPTION 'HXUV1-COWRITE-13-CLIENT_TIMESTAMP_INVALID'; END IF;
