public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_event_kind_check|c|true|false|false|false|CHECK ((event_kind = ANY (ARRAY['PAYMENT_METHOD_PREPARED'::text, 'AUTHORIZED'::text, 'SECURED'::text, 'VOIDED'::text, 'ADJUSTMENT_AUTHORIZED'::text, 'CAPTURED'::text, 'REFUNDED'::text, 'REVERSED'::text, 'SETTLEMENT_OBSERVED'::text, 'FUNDING_OBSERVED'::text, 'PROVIDER_RELEASED'::text, 'PAYOUT_OBSERVED'::text, 'BANK_SETTLEMENT_OBSERVED'::text])))
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_idempotency_key_check|c|true|false|false|false|CHECK ((idempotency_key ~ '^[A-Za-z0-9:_-]{16,128}$'::text))
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_operation_kind_check|c|true|false|false|false|CHECK ((operation_kind = ANY (ARRAY['PREPARE_PAYMENT_METHOD'::text, 'AUTHORIZE'::text, 'SECURE'::text, 'VOID'::text, 'ADJUST'::text, 'CAPTURE'::text, 'REFUND'::text, 'REVERSAL'::text, 'SETTLE'::text, 'FUND'::text, 'PROVIDER_RELEASE'::text, 'PAYOUT'::text, 'OBSERVE_BANK_SETTLEMENT'::text])))
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_pkey|p|true|false|false|true|PRIMARY KEY (prepared_command_id)
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_provider_kind_check|c|true|false|false|false|CHECK ((provider_kind = 'FAKE'::text))
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_recorded_by_fkey|f|true|false|false|true|FOREIGN KEY (recorded_by) REFERENCES public.users(id) ON DELETE RESTRICT
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_scope_hash_check|c|true|false|false|false|CHECK (((scope_hash IS NULL) OR (scope_hash ~ '^[a-f0-9]{64}$'::text)))
public.universal_v1_prepared_financial_commands.universal_v1_prepared_financial_commands_scope_version_check|c|true|false|false|false|CHECK (((scope_version IS NULL) OR (scope_version > 0)))
