  effective_event JSONB; resolution JSONB;
BEGIN
  SELECT * INTO command_record FROM public.financial_provider_command_journal WHERE command_id=p_command_id;
  SELECT * INTO request_record FROM hx_authority.fake_financial_command_outbox_requests_v13 WHERE command_id=p_command_id;
  IF command_record.command_id IS NULL OR request_record.outbox_request_id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO STRICT progress FROM public.hxos_read_fake_financial_progress_v13(
    request_record.outbox_request_id,request_record.bullmq_job_id,pg_catalog.btrim(request_record.job_authority_sha256));
  observed_at:=pg_catalog.clock_timestamp();
  SELECT * INTO bridge FROM public.universal_v1_fake_financial_lifecycle_bridges WHERE command_id=p_command_id;
  IF bridge.bridge_id IS NOT NULL THEN
    SELECT * INTO event FROM public.task_financial_security_events WHERE id=bridge.task_financial_security_event_id;
    SELECT * INTO STRICT exact FROM hx_authority.read_fake_financial_materialization_evidence_v13(
      (progress.recovery_evidence->'admission_evidence'->>'job_validation_id')::UUID,bridge.outcome_fact_id);
    -- Use the same validated terminal projection as materialization. Preserve
    -- the original admitted event identity and signed resolution timestamps.
    IF exact.provider_event->>'kind'='HX_FAKE_TERMINAL_OBSERVATION_V13' THEN
      resolution:=exact.provider_event->'resolution';
      effective_event:=(exact.provider_event->'original_event')||pg_catalog.jsonb_build_object(
        'state',exact.outcome_fact->>'provider_state','retryable',FALSE,
        'recorded_at',resolution->'provider_occurred_at','expires_at',resolution->'provider_expires_at');
    ELSE
      effective_event:=exact.provider_event;
    END IF;
    SELECT * INTO STRICT prepared FROM public.universal_v1_prepared_financial_commands
      WHERE prepared_command_id=request_record.prepared_command_id;
    expected_status:=CASE effective_event->>'state' WHEN 'DECLINED' THEN 'DECLINED' WHEN 'FAILED' THEN 'FAILED' ELSE 'SUCCEEDED' END;
    IF bridge.prepared_command_id IS DISTINCT FROM prepared.prepared_command_id
       OR bridge.dispatch_attempt_id IS DISTINCT FROM (exact.admission_evidence ->> 'dispatch_attempt_id')::UUID
       OR bridge.outcome_fact_id IS DISTINCT FROM (progress.recorded_outcome->'outcome_fact'->>'outcome_fact_id')::UUID
       OR bridge.fake_operation_event_id IS DISTINCT FROM (effective_event ->> 'event_id')::UUID
       OR event.id IS NULL
       OR event.operation_id IS DISTINCT FROM prepared.operation_id::TEXT
       OR event.idempotency_key IS DISTINCT FROM prepared.idempotency_key
       OR event.provider_kind IS DISTINCT FROM 'FAKE'
       OR event.event_kind IS DISTINCT FROM prepared.event_kind
       OR event.status IS DISTINCT FROM expected_status
       OR event.expected_version IS DISTINCT FROM prepared.lifecycle_expected_version
       OR event.task_draft_id IS DISTINCT FROM prepared.task_draft_id
       OR event.task_id IS DISTINCT FROM prepared.task_id
       OR event.eligibility_decision_id IS DISTINCT FROM prepared.eligibility_decision_id
       OR event.scope_version_id IS DISTINCT FROM prepared.scope_version_id
       OR event.change_order_id IS DISTINCT FROM prepared.change_order_id
       OR event.predecessor_event_id IS DISTINCT FROM prepared.predecessor_event_id
       OR event.completion_fact_id IS DISTINCT FROM prepared.completion_fact_id
       OR event.amount_cents IS DISTINCT FROM prepared.amount_cents
       OR event.currency IS DISTINCT FROM prepared.currency
       OR event.recorded_by IS DISTINCT FROM prepared.recorded_by
       OR event.external_reference IS DISTINCT FROM effective_event ->> 'external_reference'
       OR event.occurred_at IS DISTINCT FROM (effective_event ->> 'recorded_at')::TIMESTAMPTZ
       OR event.expires_at IS DISTINCT FROM (effective_event ->> 'expires_at')::TIMESTAMPTZ
       OR event.evidence IS DISTINCT FROM pg_catalog.jsonb_build_object(
         'providerState',effective_event ->> 'state',
         'providerOperationVersion',(effective_event ->> 'event_version')::BIGINT,
         'providerIdempotencyReplayed',FALSE
       ) THEN
      RAISE EXCEPTION 'HXUV1-FINPUBLIC-13-MATERIALIZATION_INCONSISTENT'; END IF;
    state:='MATERIALIZED';
    event_json:=pg_catalog.jsonb_build_object('id',event.id,'eventKind',event.event_kind,'status',event.status);
  ELSIF progress.recorded_outcome IS NOT NULL THEN
    -- A committed outcome awaiting materialization, UNKNOWN or pending value
    -- remains unfinished. Never report success from a raw provider event alone.
    state:='RECOVERY_REQUIRED';
  ELSIF progress.recovery_evidence->'admission_evidence' <> 'null'::JSONB THEN
    state:=CASE WHEN (progress.recovery_evidence->'admission_evidence'->>'outcome_deadline_at')::TIMESTAMPTZ <= observed_at
      THEN 'RECOVERY_REQUIRED' ELSE 'PROCESSING' END;
  ELSIF EXISTS(SELECT 1 FROM hx_authority.fake_financial_outbox_dispositions_v13 WHERE outbox_request_id=request_record.outbox_request_id)
     OR EXISTS(SELECT 1 FROM hx_authority.fake_financial_publish_exhaustions_v13 WHERE outbox_request_id=request_record.outbox_request_id)
     OR EXISTS(SELECT 1 FROM hx_authority.fake_financial_outbox_publish_outcomes_v13 WHERE outbox_request_id=request_record.outbox_request_id AND outcome_kind='TERMINAL_FAILURE')
     OR EXISTS(SELECT 1 FROM hx_authority.universal_v1_work_order_target_authority_facts WHERE supersedes_target_authority_id=request_record.target_authority_id) THEN
    state:='RECOVERY_REQUIRED';
  ELSIF EXISTS(SELECT 1 FROM hx_authority.fake_financial_outbox_publish_outcomes_v13 WHERE outbox_request_id=request_record.outbox_request_id AND outcome_kind='BULLMQ_CONFIRMED'
    AND recording_transaction_id IS DISTINCT FROM pg_catalog.pg_current_xact_id_if_assigned()) THEN state:='PUBLISHED';
  ELSE state:='REQUESTED'; END IF;
  RETURN pg_catalog.jsonb_build_object('commandId',command_record.command_id,'operationId',command_record.operation_id,
    'operationKind',command_record.operation_kind,'taskDraftId',command_record.task_draft_id,'taskId',command_record.task_id,
    'ownerActorId',command_record.recorded_actor_id,'environment',request_record.release_environment,
    'requestedAt',command_record.recorded_at,'observedAt',observed_at,
    'requestState','REQUESTED','progressState',state,'financialEvent',event_json);
END;
$function$

hx_authority.validate_fake_financial_exact_request_v13()|CREATE OR REPLACE FUNCTION hx_authority.validate_fake_financial_exact_request_v13()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  command public.financial_provider_command_journal%ROWTYPE;
  prepared public.universal_v1_prepared_financial_commands%ROWTYPE;
  request JSONB;
  request_sha256 TEXT;
  reference_count BIGINT;
  expected_reference TEXT;
  captured_amount BIGINT;
BEGIN
  SELECT * INTO command FROM public.financial_provider_command_journal
    WHERE command_id = NEW.command_id;
  IF command.command_id IS NULL OR command.provider_kind IS DISTINCT FROM 'FAKE'
     OR command.requested_transaction_id IS DISTINCT FROM pg_catalog.pg_current_xact_id()
     OR NEW.payload_contract_version IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'HXUV1-FINREQ-13-SAME_TRANSACTION_REQUIRED';
  END IF;
  SELECT * INTO prepared FROM public.universal_v1_prepared_financial_commands
    WHERE prepared_command_id = command.prepared_financial_command_id FOR SHARE;
  request := hx_authority.parse_fake_financial_request_v13(command.operation_kind, NEW.canonical_provider_request);
  request_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(NEW.canonical_provider_request, 'UTF8')), 'hex');
  IF request_sha256 IS DISTINCT FROM pg_catalog.btrim(command.request_sha256)
     OR request_sha256 IS DISTINCT FROM pg_catalog.btrim(prepared.provider_request_sha256)
     OR NEW.provider_request_sha256 IS DISTINCT FROM request_sha256
     OR (request ->> 'operationId')::UUID IS DISTINCT FROM command.operation_id
     OR request ->> 'idempotencyKey' IS DISTINCT FROM command.idempotency_key
     OR (request ->> 'expectedVersion')::BIGINT IS DISTINCT FROM command.provider_expected_version
     OR NOT EXISTS (SELECT 1 FROM hx_authority.fake_financial_command_outbox_requests_v13 outbox
       WHERE outbox.command_id = command.command_id
         AND outbox.provider_request_sha256 = request_sha256) THEN
    RAISE EXCEPTION 'HXUV1-FINREQ-13-PREPARED_OR_REQUEST_MISMATCH';
  END IF;
  IF command.operation_kind <> 'PREPARE_PAYMENT_METHOD' AND (
    (request ->> 'amountCents')::BIGINT IS DISTINCT FROM prepared.amount_cents
    OR pg_catalog.upper(request ->> 'currency') IS DISTINCT FROM prepared.currency
    OR (request ->> 'relatedOperationId')::UUID IS DISTINCT FROM prepared.related_operation_id
  ) THEN RAISE EXCEPTION 'HXUV1-FINREQ-13-EFFECT_MISMATCH'; END IF;
  IF command.operation_kind = 'SECURE'
     AND (request ->> 'authorizationOperationId')::UUID IS DISTINCT FROM prepared.related_operation_id THEN
    RAISE EXCEPTION 'HXUV1-FINREQ-13-AUTHORIZATION_MISMATCH';
  END IF;
  IF command.operation_kind = 'ADJUST' AND (
    (request ->> 'scopeVersionId')::UUID IS DISTINCT FROM prepared.scope_version_id
    OR (request ->> 'changeOrderId')::UUID IS DISTINCT FROM prepared.change_order_id
  ) THEN RAISE EXCEPTION 'HXUV1-FINREQ-13-ADJUSTMENT_MISMATCH'; END IF;
  IF command.operation_kind = 'AUTHORIZE' THEN
    SELECT pg_catalog.count(*), pg_catalog.min(event.external_reference)
      INTO reference_count, expected_reference FROM public.task_financial_security_events event
      WHERE event.operation_id = prepared.related_operation_id::TEXT
        AND event.provider_kind = 'FAKE' AND event.event_kind = 'PAYMENT_METHOD_PREPARED'
        AND event.status = 'SUCCEEDED' AND event.task_draft_id = prepared.task_draft_id
        AND ((event.task_id IS NOT DISTINCT FROM prepared.task_id
              AND event.eligibility_decision_id IS NOT DISTINCT FROM prepared.eligibility_decision_id)
          OR (event.task_id IS NULL AND event.eligibility_decision_id IS NULL AND event.scope_version_id IS NULL));
    IF reference_count <> 1 OR request ->> 'paymentMethodReference' IS DISTINCT FROM expected_reference THEN
      RAISE EXCEPTION 'HXUV1-FINREQ-13-PAYMENT_METHOD_MISMATCH';
    END IF;
  END IF;
  IF command.operation_kind = 'REFUND' THEN
    SELECT event.amount_cents INTO captured_amount FROM public.task_financial_security_events event
      WHERE event.task_draft_id = prepared.task_draft_id
        AND event.task_id IS NOT DISTINCT FROM prepared.task_id
        AND event.eligibility_decision_id IS NOT DISTINCT FROM prepared.eligibility_decision_id
        AND event.scope_version_id IS NOT DISTINCT FROM prepared.scope_version_id
        AND event.event_kind = 'CAPTURED' AND event.status = 'SUCCEEDED'
        AND event.provider_kind = 'FAKE' AND event.currency = prepared.currency
      ORDER BY event.expected_version DESC LIMIT 1;
    IF captured_amount IS NULL OR (request ->> 'originalAmountCents')::BIGINT IS DISTINCT FROM captured_amount THEN
      RAISE EXCEPTION 'HXUV1-FINREQ-13-CAPTURE_AMOUNT_MISMATCH';
    END IF;
  END IF;
  -- PREPARE's generic customer reference is authorized by the exact PREPARED
  -- hash. Terminal SUCCESS and payout account references retain the existing
  -- terminal PREPARED guard's exact request hash and account authority checks.
  NEW.provider_request_sha256 := request_sha256;
  NEW.recorded_transaction_id := pg_catalog.pg_current_xact_id();
  NEW.recorded_at := pg_catalog.clock_timestamp();
  RETURN NEW;
END;
$function$

hx_authority.validate_fake_financial_publish_claim_v13()|CREATE OR REPLACE FUNCTION hx_authority.validate_fake_financial_publish_claim_v13()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  request_record RECORD;
  latest_claim RECORD;
  latest_outcome RECORD;
  expected_claim_number INTEGER;
  requested_lease_duration INTERVAL;
  authority_now TIMESTAMPTZ;
BEGIN
  PERFORM hx_authority.assert_fake_financial_publish_open_v13(NEW.outbox_request_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hxuv1-fake-finance-publisher-v13', 0)
  );
  authority_now := pg_catalog.clock_timestamp();
  requested_lease_duration := NEW.lease_expires_at - NEW.claimed_at;
  IF requested_lease_duration < INTERVAL '1 second'
     OR requested_lease_duration > INTERVAL '5 minutes' THEN
    RAISE EXCEPTION
      'HXUV1-FINOUT-13-14: publisher lease duration is outside its bound'
      USING ERRCODE = 'P0001';
  END IF;
  NEW.claimed_at := authority_now;
  NEW.lease_expires_at := authority_now + requested_lease_duration;

  SELECT request.target_authority_id,
         request.target_database_name,
         request.release_environment,
         request.release_manifest_digest,
         request.job_authority_sha256,
         request.bullmq_job_id
    INTO request_record
    FROM hx_authority.fake_financial_command_outbox_requests_v13 request
   WHERE request.outbox_request_id = NEW.outbox_request_id
   FOR SHARE;
  IF request_record.target_authority_id IS NULL THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-15: outbox request does not exist'
      USING ERRCODE = 'P0001';
  END IF;
  PERFORM hx_authority.assert_fake_financial_outbox_target_v13(
    request_record.target_authority_id,
    request_record.target_database_name,
    request_record.release_environment,
    request_record.release_manifest_digest
  );

  SELECT claim.publish_claim_id,
         claim.claim_number,
         claim.lease_expires_at
    INTO latest_claim
    FROM hx_authority.fake_financial_outbox_publish_claims_v13 claim
   WHERE claim.outbox_request_id = NEW.outbox_request_id
   ORDER BY claim.claim_number DESC
   LIMIT 1;
  IF latest_claim.publish_claim_id IS NOT NULL THEN
    SELECT outcome.outcome_kind,
           outcome.retry_not_before
      INTO latest_outcome
      FROM hx_authority.fake_financial_outbox_publish_outcomes_v13 outcome
     WHERE outcome.publish_claim_id = latest_claim.publish_claim_id;
    IF latest_outcome.outcome_kind IN ('BULLMQ_CONFIRMED', 'TERMINAL_FAILURE')
       OR (
         latest_outcome.outcome_kind = 'RETRYABLE_FAILURE'
         AND latest_outcome.retry_not_before > authority_now
       ) OR (
         latest_outcome.outcome_kind IS NULL
         AND latest_claim.lease_expires_at > authority_now
       ) THEN
      RAISE EXCEPTION 'HXUV1-FINOUT-13-16: outbox request is not due'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT COALESCE(pg_catalog.max(claim.claim_number), 0) + 1
    INTO expected_claim_number
    FROM hx_authority.fake_financial_outbox_publish_claims_v13 claim
   WHERE claim.outbox_request_id = NEW.outbox_request_id;
  IF NEW.claim_number <> expected_claim_number OR expected_claim_number > 64 THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-17: publisher claim sequence mismatch'
      USING ERRCODE = 'P0001';
  END IF;

  NEW.claim_identity_sha256 := hx_authority.fake_financial_job_digest_v13(
    ARRAY[
      'HXUV1_FAKE_FINANCIAL_PUBLISH_CLAIM_V13',
      NEW.publish_claim_id::TEXT,
      NEW.outbox_request_id::TEXT,
      NEW.claim_number::TEXT,
      NEW.publisher_instance_id::TEXT,
      NEW.lease_duration_seconds::TEXT,
      pg_catalog.btrim(request_record.job_authority_sha256),
      request_record.bullmq_job_id
    ]::TEXT[]
  );
  RETURN NEW;
END;
$function$

hx_authority.validate_fake_financial_publish_exhaustion_v13()|CREATE OR REPLACE FUNCTION hx_authority.validate_fake_financial_publish_exhaustion_v13()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  request_record RECORD;
  latest_claim RECORD;
  latest_outcome RECORD;
  authority_now TIMESTAMPTZ;
BEGIN
  PERFORM hx_authority.assert_fake_financial_publish_open_v13(NEW.outbox_request_id);
  SELECT request.* INTO request_record
    FROM hx_authority.fake_financial_command_outbox_requests_v13 request
   WHERE request.outbox_request_id = NEW.outbox_request_id FOR SHARE;
  IF request_record.outbox_request_id IS NULL THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-43: exhaustion request does not exist'
      USING ERRCODE = 'P0001';
  END IF;
  PERFORM hx_authority.assert_fake_financial_outbox_target_v13(
    request_record.target_authority_id, request_record.target_database_name,
    request_record.release_environment, request_record.release_manifest_digest
  );
  authority_now := pg_catalog.clock_timestamp();
  SELECT claim.publish_claim_id, claim.claim_number, claim.lease_expires_at
    INTO latest_claim
    FROM hx_authority.fake_financial_outbox_publish_claims_v13 claim
   WHERE claim.outbox_request_id = NEW.outbox_request_id
   ORDER BY claim.claim_number DESC LIMIT 1;
  SELECT outcome.outcome_kind, outcome.retry_not_before INTO latest_outcome
    FROM hx_authority.fake_financial_outbox_publish_outcomes_v13 outcome
   WHERE outcome.publish_claim_id = latest_claim.publish_claim_id;
  IF latest_claim.claim_number IS DISTINCT FROM 64
     OR NEW.final_claim_number IS DISTINCT FROM 64
     OR NEW.final_publish_claim_id IS DISTINCT FROM latest_claim.publish_claim_id
     OR (
       (latest_outcome.outcome_kind IS NULL AND latest_claim.lease_expires_at <= authority_now)
       OR (latest_outcome.outcome_kind IS NOT DISTINCT FROM 'RETRYABLE_FAILURE'
           AND latest_outcome.retry_not_before <= authority_now)
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-44: exhaustion requires the exact due final publisher claim'
      USING ERRCODE = 'P0001';
  END IF;
  NEW.recorded_at := authority_now;
  NEW.exhaustion_identity_sha256 := hx_authority.fake_financial_job_digest_v13(ARRAY[
    'HXUV1_FAKE_FINANCIAL_PUBLISH_EXHAUSTION_V13',
    NEW.publish_exhaustion_id::TEXT, NEW.outbox_request_id::TEXT,
    NEW.final_publish_claim_id::TEXT, NEW.final_claim_number::TEXT,
    NEW.reason, request_record.command_id::TEXT,
    pg_catalog.btrim(request_record.job_authority_sha256)
  ]::TEXT[]);
  RETURN NEW;
END;
$function$

hx_authority.validate_fake_financial_publish_outcome_v13()|CREATE OR REPLACE FUNCTION hx_authority.validate_fake_financial_publish_outcome_v13()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  claim_record RECORD;
  request_record RECORD;
  latest_claim_id UUID;
  requested_retry_delay INTERVAL;
  authority_now TIMESTAMPTZ;
BEGIN
  NEW.recording_transaction_id := pg_catalog.pg_current_xact_id();
  PERFORM hx_authority.assert_fake_financial_publish_open_v13(NEW.outbox_request_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hxuv1-fake-finance-publisher-v13', 0)
  );
  authority_now := pg_catalog.clock_timestamp();
  IF NEW.outcome_kind = 'RETRYABLE_FAILURE' THEN
    requested_retry_delay := NEW.retry_not_before - NEW.recorded_at;
    IF requested_retry_delay < INTERVAL '1 second'
       OR requested_retry_delay > INTERVAL '1 day' THEN
      RAISE EXCEPTION 'HXUV1-FINOUT-13-20: publisher retry delay is invalid'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  NEW.recorded_at := authority_now;
  IF NEW.outcome_kind = 'RETRYABLE_FAILURE' THEN
    NEW.retry_not_before := authority_now + requested_retry_delay;
  END IF;

  SELECT claim.outbox_request_id,
         claim.claim_number
    INTO claim_record
    FROM hx_authority.fake_financial_outbox_publish_claims_v13 claim
   WHERE claim.publish_claim_id = NEW.publish_claim_id
     AND claim.outbox_request_id = NEW.outbox_request_id
   FOR SHARE;
  SELECT request.target_authority_id,
         request.target_database_name,
         request.release_environment,
         request.release_manifest_digest,
         request.bullmq_job_id,
         request.job_authority_sha256
    INTO request_record
    FROM hx_authority.fake_financial_command_outbox_requests_v13 request
   WHERE request.outbox_request_id = NEW.outbox_request_id
   FOR SHARE;
  IF claim_record.outbox_request_id IS NULL
     OR request_record.target_authority_id IS NULL THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-21: publisher outcome lacks exact claim'
      USING ERRCODE = 'P0001';
  END IF;
  PERFORM hx_authority.assert_fake_financial_outbox_target_v13(
    request_record.target_authority_id,
    request_record.target_database_name,
    request_record.release_environment,
    request_record.release_manifest_digest
  );
  SELECT claim.publish_claim_id
    INTO latest_claim_id
    FROM hx_authority.fake_financial_outbox_publish_claims_v13 claim
   WHERE claim.outbox_request_id = NEW.outbox_request_id
   ORDER BY claim.claim_number DESC
   LIMIT 1;
  IF latest_claim_id IS DISTINCT FROM NEW.publish_claim_id
     OR EXISTS (
       SELECT 1
         FROM hx_authority.fake_financial_outbox_publish_outcomes_v13 outcome
        WHERE outcome.publish_claim_id = NEW.publish_claim_id
     ) THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-22: publisher outcome is stale or duplicated'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.outcome_kind = 'BULLMQ_CONFIRMED'
     AND (
       NEW.observed_bullmq_job_id IS DISTINCT FROM request_record.bullmq_job_id
       OR NEW.observed_job_authority_sha256 IS DISTINCT FROM
            request_record.job_authority_sha256
     ) THEN
    RAISE EXCEPTION 'HXUV1-FINOUT-13-23: BullMQ acknowledgement identity mismatch'
      USING ERRCODE = 'P0001';
  END IF;

  NEW.outcome_identity_sha256 := hx_authority.fake_financial_job_digest_v13(
    ARRAY[
      'HXUV1_FAKE_FINANCIAL_PUBLISH_OUTCOME_V13',
      NEW.publish_outcome_id::TEXT,
      NEW.publish_claim_id::TEXT,
      NEW.outbox_request_id::TEXT,
      NEW.outcome_kind,
      COALESCE(NEW.observed_bullmq_job_id, ''),
      COALESCE(pg_catalog.btrim(NEW.observed_job_authority_sha256), ''),
      COALESCE(NEW.failure_code, ''),
      COALESCE(NEW.retry_delay_seconds::TEXT, '')
    ]::TEXT[]
  );
  RETURN NEW;
END;
$function$

hx_authority.validate_universal_v1_work_order_target_activation_v1()|CREATE OR REPLACE FUNCTION hx_authority.validate_universal_v1_work_order_target_activation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  current_tip RECORD;
BEGIN
  LOCK TABLE public.hxos_universal_v1_work_order_target_activation_barrier_v1
    IN ACCESS EXCLUSIVE MODE;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hxuv1-work-order-target-authority-v1', 0)
  );
  NEW.activated_at := pg_catalog.clock_timestamp();
  IF NEW.target_database_name IS DISTINCT FROM pg_catalog.current_database() THEN
    RAISE EXCEPTION 'HXUV1-WOCMD-2: target authority names a different database'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT target.target_authority_id, target.authority_version
    INTO current_tip
    FROM hx_authority.universal_v1_work_order_target_authority_facts target
   WHERE NOT EXISTS (
     SELECT 1
       FROM hx_authority.universal_v1_work_order_target_authority_facts successor
      WHERE successor.supersedes_target_authority_id = target.target_authority_id
   )
   FOR SHARE;

  IF current_tip.target_authority_id IS NULL THEN
    IF NEW.authority_version <> 1 OR NEW.supersedes_target_authority_id IS NOT NULL THEN
      RAISE EXCEPTION 'HXUV1-WOCMD-3: first target authority must be exact version one'
        USING ERRCODE = 'P0001';
    END IF;
  ELSIF NEW.authority_version <> current_tip.authority_version + 1
        OR NEW.supersedes_target_authority_id IS DISTINCT FROM
             current_tip.target_authority_id THEN
    RAISE EXCEPTION 'HXUV1-WOCMD-3: target authority must extend the one current tip'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$function$

public.assert_financial_provider_command_outcome_fact()|CREATE OR REPLACE FUNCTION public.assert_financial_provider_command_outcome_fact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  lease_action TEXT;
  lease_expiry TIMESTAMPTZ;
  command_provider_kind TEXT;
  command_operation_kind TEXT;
  command_operation_id UUID;
  command_provider_expected_version BIGINT;
  command_amount_cents BIGINT;
  command_currency CHAR(3);
  attempt_lease_id UUID;
  latest_attempt_id UUID;
  authority_now TIMESTAMPTZ;
  expected_provider_result_sha256 CHAR(64);
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtext('financial-provider-command-recovery-v1'),
    hashtext(NEW.command_id::TEXT)
  );

  authority_now := clock_timestamp();
  NEW.recorded_at := authority_now;
  NEW.recovery_not_before := CASE
    WHEN NEW.recovery_delay_seconds IS NULL THEN NULL
    ELSE authority_now + make_interval(secs => NEW.recovery_delay_seconds)
  END;

  SELECT lease.recovery_action, lease.expires_at, command.provider_kind,
         command.operation_kind, command.operation_id,
         command.provider_expected_version, command.amount_cents,
         command.currency, attempt.recovery_lease_id
    INTO lease_action, lease_expiry, command_provider_kind,
         command_operation_kind, command_operation_id,
         command_provider_expected_version, command_amount_cents,
         command_currency, attempt_lease_id
    FROM public.financial_provider_command_recovery_leases lease
    JOIN public.financial_provider_command_journal command
      ON command.command_id = lease.command_id
    JOIN public.financial_provider_command_dispatch_attempts attempt
      ON attempt.command_id = command.command_id
     AND attempt.dispatch_attempt_id = NEW.dispatch_attempt_id
   WHERE lease.recovery_lease_id = NEW.recovery_lease_id
     AND lease.command_id = NEW.command_id;
  IF NOT FOUND OR command_provider_kind <> 'FAKE' THEN
    RAISE EXCEPTION 'HXFPCREC1: outcome lacks fake command authority'
      USING ERRCODE = 'P0001';
  END IF;
  IF lease_expiry <= authority_now THEN
    RAISE EXCEPTION 'HXFPCREC1: recovery lease expired before outcome commitment'
      USING ERRCODE = 'P0001';
  END IF;
  IF lease_action = 'DISPATCH' AND attempt_lease_id <> NEW.recovery_lease_id THEN
    RAISE EXCEPTION 'HXFPCREC1: dispatch outcome is not bound to its attempt lease'
      USING ERRCODE = 'P0001';
  END IF;
  IF lease_action = 'RECONCILE' AND EXISTS (
    SELECT 1 FROM public.financial_provider_command_dispatch_attempts attempt
     WHERE attempt.recovery_lease_id = NEW.recovery_lease_id
  ) THEN
    RAISE EXCEPTION 'HXFPCREC1: reconciliation lease cannot create a dispatch attempt'
      USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.financial_provider_command_outcome_facts outcome
     WHERE outcome.recovery_lease_id = NEW.recovery_lease_id
  ) THEN
    RAISE EXCEPTION 'HXFPCREC1: recovery lease already recorded an outcome'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT attempt.dispatch_attempt_id
    INTO latest_attempt_id
    FROM public.financial_provider_command_dispatch_attempts attempt
   WHERE attempt.command_id = NEW.command_id
   ORDER BY attempt.attempt_number DESC
   LIMIT 1;
  IF latest_attempt_id <> NEW.dispatch_attempt_id THEN
    RAISE EXCEPTION 'HXFPCREC1: outcome does not reference the latest attempt'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.outcome_kind = 'OUTCOME_OBSERVED' AND NOT (
    (
      command_operation_kind IN (
        'PREPARE_PAYMENT_METHOD', 'AUTHORIZE', 'SECURE', 'ADJUST', 'CAPTURE',
        'ONBOARD_PROVIDER', 'REFRESH_PROVIDER_ACCOUNT_STATE', 'SETTLE', 'FUND',
        'PROVIDER_RELEASE', 'PAYOUT', 'OBSERVE_BANK_SETTLEMENT'
      )
      AND NEW.provider_state IN (
        'PENDING', 'SUCCEEDED', 'DECLINED', 'FAILED', 'RETRYABLE_FAILURE'
      )
    )
    OR (
      command_operation_kind = 'VOID'
      AND NEW.provider_state IN (
        'PENDING', 'VOIDED', 'DECLINED', 'FAILED', 'RETRYABLE_FAILURE'
      )
    )
    OR (
      command_operation_kind = 'REFUND'
      AND NEW.provider_state IN (
        'PENDING', 'REFUNDED', 'PARTIALLY_REFUNDED', 'DECLINED', 'FAILED',
        'RETRYABLE_FAILURE'
      )
    )
    OR (
      command_operation_kind = 'REVERSAL'
      AND NEW.provider_state IN (
        'PENDING', 'REVERSED', 'DECLINED', 'FAILED', 'RETRYABLE_FAILURE'
      )
    )
    OR (
      command_operation_kind = 'INGEST_WEBHOOK'
      AND NEW.provider_state IN ('PENDING', 'ACCEPTED', 'REJECTED', 'RETRYABLE_FAILURE')
    )
    OR (
      command_operation_kind = 'RECONCILE'
      AND NEW.provider_state IN ('MATCHED', 'MISMATCH')
    )
  ) THEN
    RAISE EXCEPTION 'HXFPCREC1: observed provider state is invalid for command operation'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.outcome_kind = 'OUTCOME_OBSERVED' THEN
    IF NEW.provider_result_version <> command_provider_expected_version + 1 THEN
      RAISE EXCEPTION 'HXFPCREC1: observed provider version does not advance exact command version'
        USING ERRCODE = 'P0001';
    END IF;
    IF command_operation_kind IN (
      'AUTHORIZE', 'SECURE', 'VOID', 'ADJUST', 'CAPTURE', 'REFUND',
      'REVERSAL', 'SETTLE', 'FUND', 'PROVIDER_RELEASE', 'PAYOUT',
      'OBSERVE_BANK_SETTLEMENT'
    ) THEN
      IF NEW.amount_cents IS DISTINCT FROM command_amount_cents
         OR NEW.currency IS DISTINCT FROM command_currency THEN
        RAISE EXCEPTION 'HXFPCREC1: observed provider value differs from exact command value'
          USING ERRCODE = 'P0001';
      END IF;
    ELSIF NEW.amount_cents IS NOT NULL OR NEW.currency IS NOT NULL THEN
      RAISE EXCEPTION 'HXFPCREC1: non-money provider outcome cannot project value'
        USING ERRCODE = 'P0001';
    END IF;

    expected_provider_result_sha256 := encode(
      public.hxos_universal_v1_sha256_bytes_v1(
        command_operation_id::TEXT || ':' || command_operation_kind || ':' ||
        command_provider_kind || ':' || NEW.provider_state || ':' ||
        NEW.provider_result_version::TEXT || ':' ||
        COALESCE(NEW.amount_cents::TEXT, '') || ':' ||
        COALESCE(NEW.currency, '') || ':' || NEW.external_reference_sha256 || ':' ||
        NEW.retryable::TEXT,
        'sha256'
      ),
      'hex'
    );
    IF NEW.provider_result_sha256 <> expected_provider_result_sha256 THEN
      RAISE EXCEPTION 'HXFPCREC1: observed provider projection digest mismatch'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.financial_provider_command_outcome_facts outcome
     WHERE outcome.command_id = NEW.command_id
       AND (
         (outcome.outcome_kind = 'OUTCOME_OBSERVED' AND outcome.retryable = FALSE)
         OR (outcome.outcome_kind = 'FAILED' AND outcome.retryable = FALSE)
       )
  ) THEN
    RAISE EXCEPTION 'HXFPCREC1: terminal outcome already exists'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$function$

public.assert_financial_provider_command_recovery_lease()|CREATE OR REPLACE FUNCTION public.assert_financial_provider_command_recovery_lease()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  current_provider_kind TEXT;
  latest_attempt_id UUID;
  latest_outcome_deadline TIMESTAMPTZ;
  latest_outcome_kind TEXT;
  latest_outcome_retryable BOOLEAN;
  latest_effect_certainty TEXT;
  latest_recovery_not_before TIMESTAMPTZ;
  authority_now TIMESTAMPTZ;
  matching_dispatch_admission_count INTEGER;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('financial-provider-command-recovery-v1'),
    pg_catalog.hashtext(NEW.command_id::TEXT)
  );

  authority_now := pg_catalog.clock_timestamp();
  NEW.acquired_at := authority_now;
  NEW.expires_at := authority_now
    + pg_catalog.make_interval(secs => NEW.lease_duration_seconds);

  SELECT command.provider_kind
    INTO current_provider_kind
    FROM public.financial_provider_command_journal command
   WHERE command.command_id = NEW.command_id
   FOR SHARE;
  IF current_provider_kind IS DISTINCT FROM 'FAKE' THEN
    RAISE EXCEPTION
      'HXFPCREC1-V13: recovery requires one existing FAKE REQUESTED command'
      USING ERRCODE = 'P0001';
  END IF;

  IF NEW.recovery_action = 'DISPATCH' THEN
    SELECT pg_catalog.count(*)::INTEGER
      INTO matching_dispatch_admission_count
      FROM hx_authority.fake_financial_dispatch_admissions_v13 admission
     WHERE admission.command_id = NEW.command_id
       AND admission.recovery_lease_id = NEW.recovery_lease_id
       AND admission.admitted_transaction_id =
             pg_catalog.pg_current_xact_id()::TEXT::BIGINT;
    IF matching_dispatch_admission_count <> 1 THEN
      RAISE EXCEPTION
        'HXFPCREC1-V13: DISPATCH requires one same-transaction sealed v13 admission'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.financial_provider_command_outcome_facts outcome
     WHERE outcome.command_id = NEW.command_id
       AND (
         (outcome.outcome_kind = 'OUTCOME_OBSERVED' AND outcome.retryable = FALSE)
         OR (outcome.outcome_kind = 'FAILED' AND outcome.retryable = FALSE)
       )
  ) THEN
    RAISE EXCEPTION 'HXFPCREC1-V13: command already has a terminal outcome'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.financial_provider_command_recovery_leases lease
     WHERE lease.command_id = NEW.command_id
       AND lease.expires_at > authority_now
       AND NOT EXISTS (
         SELECT 1
           FROM public.financial_provider_command_dispatch_attempts attempt
          WHERE attempt.recovery_lease_id = lease.recovery_lease_id
       )
       AND NOT EXISTS (
         SELECT 1
           FROM public.financial_provider_command_outcome_facts outcome
          WHERE outcome.recovery_lease_id = lease.recovery_lease_id
       )
  ) THEN
    RAISE EXCEPTION 'HXFPCREC1-V13: command already has an active recovery lease'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT attempt.dispatch_attempt_id,
         attempt.outcome_deadline_at
    INTO latest_attempt_id,
         latest_outcome_deadline
    FROM public.financial_provider_command_dispatch_attempts attempt
   WHERE attempt.command_id = NEW.command_id
   ORDER BY attempt.attempt_number DESC
   LIMIT 1;
  IF latest_attempt_id IS NOT NULL THEN
    SELECT outcome.outcome_kind,
           outcome.retryable,
           outcome.effect_certainty,
           outcome.recovery_not_before
      INTO latest_outcome_kind,
           latest_outcome_retryable,
           latest_effect_certainty,
           latest_recovery_not_before
      FROM public.financial_provider_command_outcome_facts outcome
     WHERE outcome.command_id = NEW.command_id
       AND outcome.dispatch_attempt_id = latest_attempt_id
     ORDER BY outcome.recorded_at DESC, outcome.outcome_fact_id DESC
     LIMIT 1;
  END IF;

  IF NEW.recovery_action = 'DISPATCH' THEN
    IF latest_attempt_id IS NOT NULL AND (
      latest_outcome_kind IS DISTINCT FROM 'FAILED'
      OR latest_outcome_retryable IS DISTINCT FROM TRUE
      OR latest_effect_certainty IS DISTINCT FROM 'CONFIRMED_NO_EFFECT'
      OR latest_recovery_not_before IS NULL
      OR latest_recovery_not_before > authority_now
    ) THEN
      RAISE EXCEPTION
        'HXFPCREC1-V13: redispatch requires a due retryable FAILED CONFIRMED_NO_EFFECT outcome'
        USING ERRCODE = 'P0001';
    END IF;
  ELSIF NEW.recovery_action = 'RECONCILE' THEN
    IF latest_attempt_id IS NULL THEN
      RAISE EXCEPTION 'HXFPCREC1-V13: reconciliation requires a dispatch attempt'
        USING ERRCODE = 'P0001';
    ELSIF latest_outcome_kind IS NULL THEN
      IF latest_outcome_deadline > authority_now THEN
        RAISE EXCEPTION
          'HXFPCREC1-V13: dispatch outcome deadline has not elapsed'
          USING ERRCODE = 'P0001';
      END IF;
    ELSIF latest_outcome_kind NOT IN (
      'OUTCOME_OBSERVED', 'OUTCOME_UNKNOWN', 'FAILED'
    ) OR latest_outcome_retryable IS DISTINCT FROM TRUE
       OR latest_recovery_not_before IS NULL
       OR latest_recovery_not_before > authority_now THEN
      RAISE EXCEPTION
        'HXFPCREC1-V13: reconciliation requires a due explicit nonterminal outcome'
        USING ERRCODE = 'P0001';
    END IF;
  ELSE
    RAISE EXCEPTION 'HXFPCREC1-V13: unsupported recovery action'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$function$

public.bind_universal_work_order_to_task()|CREATE OR REPLACE FUNCTION public.bind_universal_work_order_to_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  UPDATE tasks
  SET work_order_id = NEW.id,
      updated_at = clock_timestamp()
  WHERE id = NEW.task_id
    AND work_order_id IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HXUV1-WO-7: task already has a different Work Order'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$function$

public.enforce_financial_operation_trigger_only()|CREATE OR REPLACE FUNCTION public.enforce_financial_operation_trigger_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'HXUV1-FIN-18: financial operation authority is created only with its first event'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$function$

public.enforce_universal_active_scope_transition()|CREATE OR REPLACE FUNCTION public.enforce_universal_active_scope_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  active_scope public.task_scope_versions%ROWTYPE;
  approved_proposal_id UUID;
  existing_work_order_id UUID;
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.universal_contract_version IS NOT DISTINCT FROM
           NEW.universal_contract_version
     AND OLD.active_scope_version_id IS NOT DISTINCT FROM
           NEW.active_scope_version_id THEN
    RETURN NEW;
  END IF;

  IF NEW.universal_contract_version <> 1 THEN
    RETURN NEW;
  END IF;

  SELECT * INTO active_scope
    FROM public.task_scope_versions
   WHERE id = NEW.active_scope_version_id;
  IF NOT FOUND
     OR active_scope.task_id <> NEW.id
     OR active_scope.universal_contract_version <> 1 THEN
    RAISE EXCEPTION 'HXUV1-SCOPE-1: Universal V1 task must bind its exact durable scope'
      USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF active_scope.source <> 'INITIAL'
       OR active_scope.version <> 1
       OR active_scope.supersedes_version_id IS NOT NULL THEN
      RAISE EXCEPTION 'HXUV1-SCOPE-2: initial Universal V1 scope must begin the immutable task scope chain'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.universal_contract_version <> 1
     OR OLD.active_scope_version_id IS NULL THEN
    IF active_scope.source <> 'INITIAL'
       OR active_scope.version <> 1
       OR active_scope.supersedes_version_id IS NOT NULL THEN
      RAISE EXCEPTION 'HXUV1-SCOPE-2: initial Universal V1 scope must begin the immutable task scope chain'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.active_scope_version_id = OLD.active_scope_version_id THEN
    RETURN NEW;
  END IF;

  IF active_scope.source <> 'APPROVED_CHANGE'
     OR active_scope.supersedes_version_id <> OLD.active_scope_version_id
     OR NOT EXISTS (
       SELECT 1
         FROM public.task_scope_versions prior_scope
        WHERE prior_scope.id = OLD.active_scope_version_id
          AND prior_scope.task_id = NEW.id
          AND prior_scope.universal_contract_version = 1
          AND active_scope.version = prior_scope.version + 1
     ) THEN
    RAISE EXCEPTION 'HXUV1-SCOPE-3: active scope can only advance one exact immutable version'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT proposal.id INTO approved_proposal_id
    FROM public.task_scope_change_proposals proposal
   WHERE proposal.task_id = NEW.id
     AND proposal.universal_contract_version = 1
     AND proposal.status = 'APPROVED'
     AND proposal.base_version_id = OLD.active_scope_version_id
     AND proposal.approved_version_id = NEW.active_scope_version_id
     AND EXISTS (
       SELECT 1
         FROM public.task_scope_change_approvals approval
        WHERE approval.proposal_id = proposal.id
          AND approval.approver_role = 'CUSTOMER'
          AND approval.decision = 'APPROVED'
     )
     AND EXISTS (
       SELECT 1
         FROM public.task_scope_change_approvals approval
        WHERE approval.proposal_id = proposal.id
          AND approval.approver_role = 'PROVIDER'
          AND approval.decision = 'APPROVED'
     )
   ORDER BY proposal.proposal_version DESC
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HXUV1-SCOPE-4: active scope transition requires the exact dual-approved change order'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT work_order.id INTO existing_work_order_id
    FROM public.task_work_orders work_order
   WHERE work_order.task_id = NEW.id;
  IF FOUND AND NOT EXISTS (
    SELECT 1
      FROM public.task_work_order_amendments amendment
     WHERE amendment.work_order_id = existing_work_order_id
       AND amendment.change_order_id = approved_proposal_id
       AND amendment.scope_version_id = NEW.active_scope_version_id
  ) THEN
    RAISE EXCEPTION 'HXUV1-SCOPE-5: active Work Order scope transition requires its exact amendment fact'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$function$

public.enforce_universal_fake_finance_boundary()|CREATE OR REPLACE FUNCTION public.enforce_universal_fake_finance_boundary()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NEW.provider_kind='FAKE' AND NEW.task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tasks WHERE id=NEW.task_id AND universal_contract_version=1 AND automation_classification='CONTROLLED_TEST' AND worker_id IS NULL)
 THEN RAISE EXCEPTION 'HXUV1-FIN-FAKE-1: fake finance is confined to unassigned controlled-test tasks' USING ERRCODE='P0001'; END IF;
 RETURN NEW;
END $function$

public.enforce_universal_v1_dispute_release_gate_v1()|CREATE OR REPLACE FUNCTION public.enforce_universal_v1_dispute_release_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  checked_work_order_id UUID;
BEGIN
  IF TG_TABLE_NAME = 'universal_v1_fake_terminal_lifecycle_intents' THEN
    IF NEW.terminal_path <> 'SETTLED' THEN RETURN NEW; END IF;
    checked_work_order_id := NEW.work_order_id;
  ELSIF TG_TABLE_NAME = 'universal_v1_prepared_financial_commands' THEN
    IF NEW.operation_kind NOT IN ('PROVIDER_RELEASE', 'PAYOUT') THEN RETURN NEW; END IF;
    -- This gate sorts before the prepared-command authority trigger. Derive the
    -- same exact current Work Order from PostgreSQL instead of trusting a
    -- caller value that the later authority trigger deliberately overwrites.
    SELECT work_order.id INTO checked_work_order_id
      FROM public.tasks task
      JOIN public.task_work_orders work_order
        ON work_order.id = task.work_order_id
       AND work_order.task_id = task.id
       AND work_order.task_draft_id = NEW.task_draft_id
     WHERE task.id = NEW.task_id;
  ELSIF TG_TABLE_NAME = 'financial_provider_command_journal' THEN
    IF NEW.operation_kind NOT IN ('PROVIDER_RELEASE', 'PAYOUT') THEN RETURN NEW; END IF;
    checked_work_order_id := NEW.work_order_id;
  ELSIF TG_TABLE_NAME = 'task_financial_security_events' THEN
    IF NEW.event_kind NOT IN ('PROVIDER_RELEASED', 'PAYOUT_OBSERVED') THEN RETURN NEW; END IF;
    SELECT work_order.id INTO checked_work_order_id
    FROM public.task_work_orders work_order
    WHERE work_order.task_id = NEW.task_id;
  END IF;

  IF checked_work_order_id IS NULL THEN
    RAISE EXCEPTION 'HXUDR9: release/payout authority lacks an exact Work Order binding'
      USING ERRCODE = 'P0001';
  END IF;
  PERFORM public.universal_v1_dispute_lock_v1(checked_work_order_id);
  IF public.universal_v1_has_open_material_dispute_v1(checked_work_order_id) THEN
    RAISE EXCEPTION 'HXUDR9: material dispute blocks new provider release or payout intent'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$function$

public.enforce_universal_v1_fake_expiry_bridge_v9()|CREATE OR REPLACE FUNCTION public.enforce_universal_v1_fake_expiry_bridge_v9()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  admitted_result RECORD;
  original_event JSONB;
  resolution JSONB;
  admitted_id UUID;
  outcome_resolution_version SMALLINT;
  resolution_suffix TEXT := '';
  expiry_prefix TEXT := '';
  raw_recorded_at TIMESTAMPTZ;
  raw_expiry TIMESTAMPTZ;
  lifecycle_occurred_at TIMESTAMPTZ;
  lifecycle_expiry TIMESTAMPTZ;
  exact_expiry_authority_sha256 CHAR(64);
BEGIN
  SELECT raw.recorded_at, raw.expires_at
    INTO raw_recorded_at, raw_expiry
    FROM public.hxos_fake_financial_operation_events_v1 raw
   WHERE raw.event_id = NEW.fake_operation_event_id
   FOR SHARE;
  SELECT lifecycle.occurred_at, lifecycle.expires_at
    INTO lifecycle_occurred_at, lifecycle_expiry
    FROM public.task_financial_security_events lifecycle
   WHERE lifecycle.id = NEW.task_financial_security_event_id
   FOR SHARE;

  SELECT resolution_contract_version INTO outcome_resolution_version
    FROM public.financial_provider_command_outcome_facts WHERE outcome_fact_id=NEW.outcome_fact_id;
  IF outcome_resolution_version IS NOT NULL THEN
    IF outcome_resolution_version<>1 OR NEW.resolution_contract_version IS DISTINCT FROM outcome_resolution_version THEN RAISE EXCEPTION 'HXUV1-FINMATERIALIZE-13-EXPIRY_RESOLUTION_VERSION'; END IF;
    SELECT admitted_job_validation_id INTO admitted_id
      FROM public.hxos_fake_financial_operation_events_v1 WHERE event_id=NEW.fake_operation_event_id;
    SELECT * INTO admitted_result FROM hx_authority.read_fake_financial_materialization_evidence_v13(admitted_id,NEW.outcome_fact_id);
    original_event:=admitted_result.provider_event->'original_event';
    resolution:=admitted_result.provider_event->'resolution';
    IF admitted_result.provider_event->>'kind' IS DISTINCT FROM 'HX_FAKE_TERMINAL_OBSERVATION_V13'
       OR original_event->>'event_id' IS DISTINCT FROM NEW.fake_operation_event_id::TEXT
       OR (resolution->>'observation_id')::UUID IS DISTINCT FROM NEW.resolution_observation_id
       OR (resolution->>'receipt_id')::UUID IS DISTINCT FROM NEW.resolution_receipt_id
       OR resolution->>'resolution_identity_sha256' IS DISTINCT FROM NEW.resolution_identity_sha256 THEN
      RAISE EXCEPTION 'HXUV1-FINMATERIALIZE-13-EXPIRY_RESOLUTION_MISMATCH';
    END IF;
    raw_recorded_at:=(resolution->>'provider_occurred_at')::TIMESTAMPTZ;
    raw_expiry:=(resolution->>'provider_expires_at')::TIMESTAMPTZ;
    expiry_prefix:='HUSTLEXP_UNIVERSAL_V1_FAKE_EXPIRY_RESOLUTION_V1:';
    resolution_suffix:=':1:'||NEW.resolution_observation_id::TEXT||':'||NEW.resolution_receipt_id::TEXT||':'||NEW.resolution_identity_sha256;
  ELSIF NEW.resolution_contract_version IS NOT NULL OR NEW.resolution_observation_id IS NOT NULL
    OR NEW.resolution_receipt_id IS NOT NULL OR NEW.resolution_identity_sha256 IS NOT NULL THEN
    RAISE EXCEPTION 'HXUV1-FINMATERIALIZE-13-EXPIRY_RESOLUTION_MISMATCH';
  END IF;

  IF raw_recorded_at IS NULL
     OR raw_recorded_at IS DISTINCT FROM lifecycle_occurred_at
     OR raw_expiry IS DISTINCT FROM lifecycle_expiry THEN
    RAISE EXCEPTION 'HXUV1-FSE-V9-1: canonical provider time and expiry are not the exact raw fake-provider facts'
      USING ERRCODE = 'P0001';
  END IF;

  exact_expiry_authority_sha256 := encode(
    public.hxos_universal_v1_sha256_bytes_v1(
      expiry_prefix || NEW.fake_operation_event_id::TEXT || ':' ||
      NEW.task_financial_security_event_id::TEXT || ':' ||
      ((extract(epoch FROM raw_recorded_at) * 1000000)::BIGINT)::TEXT || ':' ||
      COALESCE(
        ((extract(epoch FROM raw_expiry) * 1000000)::BIGINT)::TEXT,
        'NO_EXPIRY'
      ) || resolution_suffix,
      'sha256'
    ),
    'hex'
  );

  IF NEW.provider_recorded_at IS NOT NULL
     AND NEW.provider_recorded_at IS DISTINCT FROM raw_recorded_at THEN
    RAISE EXCEPTION 'HXUV1-FSE-V9-2: bridge provider occurrence differs from raw provider truth'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.provider_expires_at IS NOT NULL
     AND NEW.provider_expires_at IS DISTINCT FROM raw_expiry THEN
    RAISE EXCEPTION 'HXUV1-FSE-V9-3: bridge provider expiry differs from raw provider truth'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.expiry_authority_sha256 IS NOT NULL
     AND NEW.expiry_authority_sha256 IS DISTINCT FROM exact_expiry_authority_sha256 THEN
    RAISE EXCEPTION 'HXUV1-FSE-V9-4: bridge expiry authority digest differs from exact facts'
      USING ERRCODE = 'P0001';
  END IF;

  NEW.provider_recorded_at := raw_recorded_at;
  NEW.provider_expires_at := raw_expiry;
  NEW.expiry_authority_sha256 := exact_expiry_authority_sha256;
  RETURN NEW;
END;
$function$

public.enforce_universal_v1_task_opportunity_interest_v1()|CREATE OR REPLACE FUNCTION public.enforce_universal_v1_task_opportunity_interest_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  opportunity public.current_universal_v1_task_opportunities_v1%ROWTYPE;
  provider public.users%ROWTYPE;
  profile public.capability_profiles%ROWTYPE;
  organization public.business_organizations%ROWTYPE;
  credential public.business_credentials%ROWTYPE;
  expected_request_sha256 CHAR(64);
  capability_snapshot JSONB;
  trade_qualification RECORD;
  trade_qualification_snapshot JSONB;
BEGIN
  IF NEW.opportunity_contract_version <> 1 THEN
    RETURN NEW;
  END IF;

  IF NEW.universal_contract_version <> 1
     OR NEW.authority <> 'EXPRESS_INTEREST'
     OR NEW.status <> 'pending'
     OR NEW.task_id IS NOT NULL
     OR NEW.interest_scope_version_id IS NOT NULL
     OR NEW.idempotency_key IS NULL
     OR NEW.request_sha256 IS NULL
     OR NEW.message IS NOT NULL
     OR NEW.rejection_reason IS NOT NULL
     OR NEW.counter_offer_round <> 0 THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-1: TaskDraft interest must remain a bounded EXPRESS_INTEREST observation'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO opportunity
  FROM public.current_universal_v1_task_opportunities_v1 current_opportunity
  WHERE current_opportunity.opportunity_id = NEW.opportunity_id
    AND current_opportunity.opportunity_version = NEW.opportunity_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-2: exact current open TaskDraft opportunity version is unavailable'
      USING ERRCODE = 'P0001';
  END IF;

  IF (NEW.task_draft_id IS NOT NULL
        AND NEW.task_draft_id IS DISTINCT FROM opportunity.task_draft_id)
     OR (NEW.interest_routing_decision_id IS NOT NULL
        AND NEW.interest_routing_decision_id IS DISTINCT FROM opportunity.routing_decision_id)
     OR (NEW.interest_routing_decision_version IS NOT NULL
        AND NEW.interest_routing_decision_version IS DISTINCT FROM opportunity.routing_decision_version)
     OR (NEW.interest_relationship_origin_id IS NOT NULL
        AND NEW.interest_relationship_origin_id IS DISTINCT FROM opportunity.relationship_origin_id)
     OR (NEW.interest_relationship_origin_version IS NOT NULL
        AND NEW.interest_relationship_origin_version IS DISTINCT FROM opportunity.relationship_origin_version)
     OR (NEW.interest_scope_artifact_kind IS NOT NULL
        AND NEW.interest_scope_artifact_kind IS DISTINCT FROM opportunity.scope_artifact_kind)
     OR (NEW.interest_scope_artifact_id IS NOT NULL
        AND NEW.interest_scope_artifact_id IS DISTINCT FROM opportunity.scope_artifact_id)
     OR (NEW.interest_scope_artifact_version IS NOT NULL
        AND NEW.interest_scope_artifact_version IS DISTINCT FROM opportunity.scope_artifact_version)
     OR (NEW.interest_scope_artifact_sha256 IS NOT NULL
        AND btrim(NEW.interest_scope_artifact_sha256) IS DISTINCT FROM
            btrim(opportunity.scope_artifact_sha256)) THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-3: forged route, origin, or scope artifact binding'
      USING ERRCODE = 'P0001';
  END IF;

  -- Lock the mutable TaskDraft pointer, then re-read the projection. Route,
  -- origin, cell, and scope evidence are append-only facts.
  PERFORM 1
  FROM public.task_drafts draft
  WHERE draft.id = opportunity.task_draft_id
  FOR SHARE;
  SELECT * INTO opportunity
  FROM public.current_universal_v1_task_opportunities_v1 current_opportunity
  WHERE current_opportunity.opportunity_id = NEW.opportunity_id
    AND current_opportunity.opportunity_version = NEW.opportunity_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-3: TaskDraft opportunity changed before interest recording'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO provider
  FROM public.users actor
  WHERE actor.id = NEW.hustler_id
  FOR SHARE;
  IF NOT FOUND
     OR provider.account_status <> 'ACTIVE'
     OR provider.is_minor IS NOT FALSE
     OR COALESCE(provider.is_banned, FALSE) IS TRUE THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-4: active adult provider identity observation is required'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO profile
  FROM public.capability_profiles capability
  WHERE capability.user_id = NEW.hustler_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-5: provider capability observation is unresolved'
      USING ERRCODE = 'P0001';
  END IF;

  capability_snapshot := jsonb_build_object(
    'providerClass', profile.provider_class,
    'trustTier', profile.trust_tier,
    'riskClearance', profile.risk_clearance,
    'insuranceValid', profile.insurance_valid,
    'insuranceExpiresAt', profile.insurance_expires_at,
    'backgroundCheckValid', profile.background_check_valid,
    'backgroundCheckExpiresAt', profile.background_check_expires_at,
    'locationState', profile.location_state,
    'updatedAt', profile.updated_at
  );

  IF NEW.provider_organization_id IS NULL THEN
    IF NEW.observed_trade_credential_id IS NOT NULL
       OR profile.provider_class <> 'GENERAL_SERVICE_PROVIDER' THEN
      RAISE EXCEPTION 'HXUV1-OPPORTUNITY-6: individual general-provider observation is unresolved'
        USING ERRCODE = 'P0001';
    END IF;
    NEW.provider_class_snapshot := 'GENERAL_SERVICE_PROVIDER';
    NEW.trade_credential_observed_at := NULL;
    NEW.trade_credential_evidence_sha256 := NULL;
    NEW.trade_qualification_sha256 := NULL;
  ELSE
    SELECT * INTO organization
    FROM public.business_organizations candidate
    WHERE candidate.id = NEW.provider_organization_id
    FOR SHARE;
    IF NOT FOUND
       OR organization.status <> 'ACTIVE'
       OR organization.verification_status <> 'VERIFIED'
       OR organization.provider_enabled IS NOT TRUE
       OR NOT EXISTS (
         SELECT 1
         FROM public.business_memberships membership
         WHERE membership.organization_id = organization.id
           AND membership.user_id = NEW.hustler_id
           AND membership.status = 'ACTIVE'
           AND membership.role IN ('OWNER', 'ADMIN', 'DISPATCHER', 'CREW')
       ) THEN
      RAISE EXCEPTION 'HXUV1-OPPORTUNITY-7: active provider-business membership observation is unresolved'
        USING ERRCODE = 'P0001';
    END IF;

    IF organization.provider_class = 'GENERAL_SERVICE_PROVIDER' THEN
      IF NEW.observed_trade_credential_id IS NOT NULL
         OR profile.provider_class <> 'GENERAL_SERVICE_PROVIDER' THEN
        RAISE EXCEPTION 'HXUV1-OPPORTUNITY-8: general-provider business observation is inconsistent'
          USING ERRCODE = 'P0001';
      END IF;
      NEW.provider_class_snapshot := 'GENERAL_SERVICE_PROVIDER';
      NEW.trade_credential_observed_at := NULL;
      NEW.trade_credential_evidence_sha256 := NULL;
      NEW.trade_qualification_sha256 := NULL;
    ELSIF organization.provider_class = 'VERIFIED_TRADE_BUSINESS' THEN
      IF NEW.observed_trade_credential_id IS NULL THEN
        RAISE EXCEPTION 'HXUV1-OPPORTUNITY-9: Verified Trade Business interest requires one exact credential observation'
          USING ERRCODE = 'P0001';
      END IF;
      SELECT * INTO credential
      FROM public.business_credentials candidate
      WHERE candidate.id = NEW.observed_trade_credential_id
        AND candidate.organization_id = organization.id
      FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'HXUV1-OPPORTUNITY-9: Verified Trade Business credential observation is unavailable'
          USING ERRCODE = 'P0001';
      END IF;
      IF profile.provider_class <> 'VERIFIED_TRADE_BUSINESS' THEN
        RAISE EXCEPTION 'HXUV1-OPPORTUNITY-10: Verified Trade Business capability observation is unresolved'
          USING ERRCODE = 'P0001';
      END IF;
      SELECT
        qualification.issuing_authority,
        qualification.jurisdiction_code,
        qualification.license_scope,
        qualification.license_status,
        qualification.expires_at,
        qualification.evidence_hash,
        qualification.verified_at,
        qualification.official_source_checked_at,
        permitted.category AS permitted_category
      INTO trade_qualification
        FROM public.current_verified_trade_qualifications qualification
        CROSS JOIN LATERAL unnest(qualification.permitted_work_categories)
          permitted(category)
        WHERE qualification.provider_user_id = NEW.hustler_id
          AND qualification.organization_id = organization.id
          AND qualification.business_credential_id = credential.id
          AND qualification.jurisdiction_code = opportunity.region_code
          AND lower(permitted.category) = opportunity.work_category_code
        ORDER BY permitted.category
        LIMIT 1;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'HXUV1-OPPORTUNITY-10: active credential/category/jurisdiction observation is unresolved'
          USING ERRCODE = 'P0001';
      END IF;
      trade_qualification_snapshot := jsonb_build_object(
        'credentialId', credential.id,
        'organizationId', organization.id,
        'issuingAuthority', trade_qualification.issuing_authority,
        'jurisdictionCode', trade_qualification.jurisdiction_code,
        'licenseScope', trade_qualification.license_scope,
        'licenseStatus', trade_qualification.license_status,
        'expiresAt', trade_qualification.expires_at,
        'evidenceHash', trade_qualification.evidence_hash,
        'verifiedAt', trade_qualification.verified_at,
        'officialSourceCheckedAt', trade_qualification.official_source_checked_at,
        'permittedCategory', lower(trade_qualification.permitted_category)
      );
      NEW.provider_class_snapshot := 'VERIFIED_TRADE_BUSINESS';
      NEW.trade_credential_observed_at := credential.updated_at;
      NEW.trade_credential_evidence_sha256 := credential.evidence_hash;
      NEW.trade_qualification_sha256 := encode(
        public.hxos_universal_v1_sha256_bytes_v1(trade_qualification_snapshot::TEXT, 'sha256'),
        'hex'
      );
    ELSE
      RAISE EXCEPTION 'HXUV1-OPPORTUNITY-11: provider-business class observation is unresolved'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  expected_request_sha256 :=
    public.universal_v1_task_opportunity_interest_request_sha256(
      NEW.hustler_id,
      NEW.opportunity_id,
      NEW.opportunity_version,
      NEW.provider_organization_id,
      NEW.observed_trade_credential_id,
      NEW.idempotency_key
    );
  IF btrim(NEW.request_sha256) IS DISTINCT FROM btrim(expected_request_sha256) THEN
    RAISE EXCEPTION 'HXUV1-OPPORTUNITY-12: EXPRESS_INTEREST request witness mismatch'
      USING ERRCODE = 'P0001';
  END IF;

  NEW.task_id := NULL;
  NEW.task_draft_id := opportunity.task_draft_id;
  NEW.interest_routing_decision_id := opportunity.routing_decision_id;
  NEW.interest_routing_decision_version := opportunity.routing_decision_version;
  NEW.interest_relationship_origin_id := opportunity.relationship_origin_id;
  NEW.interest_relationship_origin_version := opportunity.relationship_origin_version;
  NEW.interest_scope_artifact_kind := opportunity.scope_artifact_kind;
  NEW.interest_scope_artifact_id := opportunity.scope_artifact_id;
  NEW.interest_scope_artifact_version := opportunity.scope_artifact_version;
  NEW.interest_scope_artifact_sha256 := opportunity.scope_artifact_sha256;
  NEW.provider_capability_observed_at := profile.updated_at;
  NEW.provider_capability_sha256 := encode(
    public.hxos_universal_v1_sha256_bytes_v1(capability_snapshot::TEXT, 'sha256'),
    'hex'
  );
  NEW.provider_binding_sha256 := encode(public.hxos_universal_v1_sha256_bytes_v1(concat_ws('|',
    'HX_UNIVERSAL_V1_PROVIDER_BINDING_V1',
    NEW.hustler_id::TEXT,
    COALESCE(NEW.provider_organization_id::TEXT, '')
  ), 'sha256'), 'hex');
  NEW.created_at := clock_timestamp();
  NEW.updated_at := NEW.created_at;
  RETURN NEW;
END;
$function$

public.ensure_universal_v1_marketplace_relationship_origin(uuid)|CREATE OR REPLACE FUNCTION public.ensure_universal_v1_marketplace_relationship_origin(exact_task_draft_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  draft public.task_drafts%ROWTYPE;
  initiator_id UUID;
  customer_identity_id UUID;
  customer_consent_id UUID;
  origin_id UUID;
  source_digest CHAR(64);
BEGIN
  SELECT * INTO draft
    FROM public.task_drafts
   WHERE id = exact_task_draft_id
   FOR UPDATE;
  IF NOT FOUND
     OR draft.relationship_origin_contract_version <> 1
     OR draft.relationship_origin_kind <> 'MARKETPLACE'
     OR draft.relationship_origin_policy_version <> 1
     OR draft.relationship_origin_intake_consent_version <> 'v1' THEN
    RAISE EXCEPTION 'HXUV1-REL-25: Marketplace bootstrap requires the exact v1 TaskDraft intake contract'
      USING ERRCODE = 'P0001';
  END IF;

  initiator_id := public.universal_v1_relationship_deterministic_uuid(
    'relationship-origin-observation:' || draft.id::TEXT ||
    ':INITIATOR_IDENTITY_OBSERVED:v1'
  );
  customer_identity_id := public.universal_v1_relationship_deterministic_uuid(
    'relationship-origin-observation:' || draft.id::TEXT ||
    ':CUSTOMER_IDENTITY_OBSERVED:v1'
  );
  customer_consent_id := public.universal_v1_relationship_deterministic_uuid(
    'relationship-origin-observation:' || draft.id::TEXT ||
    ':CUSTOMER_CONSENT_OBSERVED:v1'
  );

  source_digest := pg_catalog.encode(public.hxos_universal_v1_sha256_bytes_v1(
    'MARKETPLACE_INITIATOR|' || draft.id::TEXT || '|' || draft.card_token_hash,
    'sha256'
  ), 'hex')::CHAR(64);
  INSERT INTO public.universal_v1_relationship_origin_observations (
    id, task_draft_id, policy_version, origin_kind, observation_version,
    observation_kind, subject_role, identity_basis,
    subject_binding_sha256, source_evidence_sha256
  ) VALUES (
    initiator_id, draft.id, 1, 'MARKETPLACE', 1,
    'INITIATOR_IDENTITY_OBSERVED', 'CUSTOMER', 'TASK_DRAFT_CAPABILITY',
    draft.card_token_hash, source_digest
  ) ON CONFLICT (task_draft_id, observation_kind, observation_version) DO NOTHING;

  source_digest := pg_catalog.encode(public.hxos_universal_v1_sha256_bytes_v1(
    'MARKETPLACE_CUSTOMER|' || draft.id::TEXT || '|' || draft.card_token_hash,
    'sha256'
  ), 'hex')::CHAR(64);
  INSERT INTO public.universal_v1_relationship_origin_observations (
    id, task_draft_id, policy_version, origin_kind, observation_version,
    observation_kind, subject_role, identity_basis,
    subject_binding_sha256, source_evidence_sha256
  ) VALUES (
    customer_identity_id, draft.id, 1, 'MARKETPLACE', 1,
    'CUSTOMER_IDENTITY_OBSERVED', 'CUSTOMER', 'TASK_DRAFT_CAPABILITY',
    draft.card_token_hash, source_digest
  ) ON CONFLICT (task_draft_id, observation_kind, observation_version) DO NOTHING;

  source_digest := pg_catalog.encode(public.hxos_universal_v1_sha256_bytes_v1(
    'MARKETPLACE_CUSTOMER_CONSENT|' || draft.id::TEXT || '|v1|' ||
    draft.card_token_hash, 'sha256'
  ), 'hex')::CHAR(64);
  INSERT INTO public.universal_v1_relationship_origin_observations (
    id, task_draft_id, policy_version, origin_kind, observation_version,
    observation_kind, subject_role, identity_basis,
    subject_binding_sha256, consent_contract_version,
    source_evidence_sha256
  ) VALUES (
    customer_consent_id, draft.id, 1, 'MARKETPLACE', 1,
    'CUSTOMER_CONSENT_OBSERVED', 'CUSTOMER', 'TASK_DRAFT_CAPABILITY',
    draft.card_token_hash, 'v1', source_digest
  ) ON CONFLICT (task_draft_id, observation_kind, observation_version) DO NOTHING;

  origin_id := public.universal_v1_relationship_deterministic_uuid(
    'relationship-origin:' || draft.id::TEXT || ':v1'
  );
  INSERT INTO public.universal_v1_relationship_origins (
    id, task_draft_id, policy_version, origin_kind, origin_version,
    initiator_identity_observation_id, customer_identity_observation_id,
    customer_consent_observation_id
  ) VALUES (
    origin_id, draft.id, 1, 'MARKETPLACE', 1,
    initiator_id, customer_identity_id, customer_consent_id
  ) ON CONFLICT (task_draft_id, origin_version) DO NOTHING;

  IF NOT EXISTS (
    SELECT 1
      FROM public.universal_v1_relationship_origins origin
      JOIN public.universal_v1_relationship_origin_observations initiator
        ON initiator.id = origin.initiator_identity_observation_id
      JOIN public.universal_v1_relationship_origin_observations customer_identity
        ON customer_identity.id = origin.customer_identity_observation_id
      JOIN public.universal_v1_relationship_origin_observations customer_consent
        ON customer_consent.id = origin.customer_consent_observation_id
     WHERE origin.id = origin_id
       AND origin.task_draft_id = draft.id
       AND origin.origin_kind = 'MARKETPLACE'
       AND origin.policy_version = 1
       AND origin.origin_version = 1
       AND origin.initiator_identity_observation_id = initiator_id
       AND origin.customer_identity_observation_id = customer_identity_id
       AND origin.customer_consent_observation_id = customer_consent_id
       AND origin.provider_link_observation_id IS NULL
       AND origin.provider_consent_observation_id IS NULL
       AND origin.routing_state = 'ROUTING_READY'
       AND pg_catalog.cardinality(origin.hold_reason_codes) = 0
       AND initiator.source_evidence_sha256 = pg_catalog.encode(
         public.hxos_universal_v1_sha256_bytes_v1(
           'MARKETPLACE_INITIATOR|' || draft.id::TEXT || '|' || draft.card_token_hash,
           'sha256'
         ), 'hex')::CHAR(64)
       AND customer_identity.source_evidence_sha256 = pg_catalog.encode(
         public.hxos_universal_v1_sha256_bytes_v1(
           'MARKETPLACE_CUSTOMER|' || draft.id::TEXT || '|' || draft.card_token_hash,
           'sha256'
         ), 'hex')::CHAR(64)
       AND customer_consent.source_evidence_sha256 = pg_catalog.encode(
         public.hxos_universal_v1_sha256_bytes_v1(
           'MARKETPLACE_CUSTOMER_CONSENT|' || draft.id::TEXT || '|v1|' ||
           draft.card_token_hash, 'sha256'
         ), 'hex')::CHAR(64)
  ) THEN
    RAISE EXCEPTION 'HXUV1-REL-26: Marketplace bootstrap replay does not match exact certified evidence'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN origin_id;
END;
$function$

public.hxos_acquire_fake_financial_reconcile_lease_v13(uuid,uuid,uuid,integer)|CREATE OR REPLACE FUNCTION public.hxos_acquire_fake_financial_reconcile_lease_v13(p_job_validation_id uuid, p_worker_instance_id uuid, p_recovery_lease_id uuid, p_lease_duration_seconds integer)
 RETURNS TABLE(admission_evidence jsonb, recovery_lease jsonb, idempotency_replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  evidence JSONB;
  command_uuid UUID;
  stored public.financial_provider_command_recovery_leases%ROWTYPE;
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'HXUV1-FINOUTCOME-13-READ_COMMITTED_REQUIRED';
  END IF;
  IF p_job_validation_id IS NULL OR p_worker_instance_id IS NULL OR p_recovery_lease_id IS NULL
     OR p_lease_duration_seconds IS NULL OR p_lease_duration_seconds NOT BETWEEN 1 AND 900 THEN
    RAISE EXCEPTION 'HXUV1-FINOUTCOME-13-LEASE_INPUT_INVALID';
  END IF;
  evidence := hx_authority.read_fake_financial_outcome_admission_v13(p_job_validation_id);
  command_uuid := (evidence ->> 'command_id')::UUID;
  -- Use the same serialization boundary as execution and the existing guards.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('financial-provider-command-recovery-v1'), pg_catalog.hashtext(command_uuid::TEXT)
  );
  SELECT lease.* INTO stored FROM public.financial_provider_command_recovery_leases lease
   WHERE lease.recovery_lease_id = p_recovery_lease_id;
  IF stored.recovery_lease_id IS NOT NULL THEN
    IF stored.command_id IS DISTINCT FROM command_uuid OR stored.recovery_action IS DISTINCT FROM 'RECONCILE'
       OR stored.lease_owner_id IS DISTINCT FROM p_worker_instance_id
       OR stored.admitted_job_validation_id IS DISTINCT FROM p_job_validation_id
       OR stored.lease_duration_seconds IS DISTINCT FROM p_lease_duration_seconds
       OR stored.expires_at IS DISTINCT FROM stored.acquired_at + pg_catalog.make_interval(secs => p_lease_duration_seconds) THEN
      RAISE EXCEPTION 'HXUV1-FINOUTCOME-13-LEASE_REPLAY_CONFLICT';
    END IF;
    RETURN QUERY SELECT evidence, pg_catalog.to_jsonb(stored), TRUE;
    RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM public.financial_provider_command_outcome_facts fence
    WHERE fence.dispatch_attempt_id=(evidence->>'dispatch_attempt_id')::UUID
      AND fence.outcome_kind='FAILED' AND fence.failure_code='FAKE_ADMISSION_FENCED_NO_EFFECT') THEN
    RAISE EXCEPTION 'HXUV1-FINFENCE-13-DISPATCH_ALREADY_FENCED'; END IF;
  IF (SELECT attempt.dispatch_attempt_id
        FROM public.financial_provider_command_dispatch_attempts attempt
       WHERE attempt.command_id = command_uuid ORDER BY attempt.attempt_number DESC LIMIT 1)
       IS DISTINCT FROM (evidence ->> 'dispatch_attempt_id')::UUID THEN
    RAISE EXCEPTION 'HXUV1-FINOUTCOME-13-LATEST_ATTEMPT_REQUIRED';
  END IF;
  -- The existing trigger owns due-time, terminal-outcome, active-lease checks
  -- and both timestamps. Stable UUID replay above never renews the window.
  INSERT INTO public.financial_provider_command_recovery_leases (
    recovery_lease_id, command_id, recovery_action, lease_owner_id, lease_duration_seconds, admitted_job_validation_id
  ) VALUES (p_recovery_lease_id, command_uuid, 'RECONCILE', p_worker_instance_id, p_lease_duration_seconds, p_job_validation_id)
  RETURNING * INTO stored;
  RETURN QUERY SELECT evidence, pg_catalog.to_jsonb(stored), FALSE;
END;
$function$

public.hxos_build_change_order_actor_request_v13(text,jsonb)|CREATE OR REPLACE FUNCTION public.hxos_build_change_order_actor_request_v13(expected_command_kind text, command_payload jsonb)
 RETURNS TABLE(target_authority_id uuid, environment text, release_manifest_sha256 text, canonical_request jsonb, actor_request_sha256 text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  target RECORD; allowed_keys TEXT[]; version_fields TEXT[]; field_name TEXT;
  text_value TEXT; scope_payload JSONB; entry JSONB; minimum_length INTEGER; maximum_length INTEGER;
  utf16_length INTEGER;
  -- ECMAScript String.trim whitespace, matching the normalized public schema.
  trim_chars TEXT:=pg_catalog.chr(9)||pg_catalog.chr(10)||pg_catalog.chr(11)||pg_catalog.chr(12)||
    pg_catalog.chr(13)||pg_catalog.chr(32)||pg_catalog.chr(160)||pg_catalog.chr(5760)||
    pg_catalog.chr(8192)||pg_catalog.chr(8193)||pg_catalog.chr(8194)||pg_catalog.chr(8195)||
    pg_catalog.chr(8196)||pg_catalog.chr(8197)||pg_catalog.chr(8198)||pg_catalog.chr(8199)||
    pg_catalog.chr(8200)||pg_catalog.chr(8201)||pg_catalog.chr(8202)||pg_catalog.chr(8232)||
    pg_catalog.chr(8233)||pg_catalog.chr(8239)||pg_catalog.chr(8287)||pg_catalog.chr(12288)||pg_catalog.chr(65279);
BEGIN
